CREATE OR REPLACE FUNCTION public.protect_session_lifecycle() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF auth.uid() IS NOT NULL THEN IF NEW.host_id IS DISTINCT FROM OLD.host_id OR NEW.mode IS DISTINCT FROM OLD.mode THEN RAISE EXCEPTION 'Session host and mode cannot be changed'; END IF; IF NEW.status IS DISTINCT FROM OLD.status AND auth.uid() <> OLD.host_id THEN RAISE EXCEPTION 'Only the host can manage this session'; END IF; END IF; RETURN NEW; END; $$;
CREATE TRIGGER protect_session_lifecycle BEFORE UPDATE ON public.sessions FOR EACH ROW EXECUTE FUNCTION public.protect_session_lifecycle();